            this.spacing = Signals.constant(spacing);
            this.spacingToken = null;
            return this;
        }

        /** Bind the main-axis gap to a signal. */
        public Config spacing(Signal<Float> spacing) {
            this.spacing = spacing;
            this.spacingToken = null;
            return this;
