package dev.pathland.view;

/**
 * A reusable view modifier ({@code ViewModifier}). External developers wrap
 * any view with custom styling logic:
 *
 * <pre>{@code
 * View card = content.modifiers(new CardStyle());
 * }</pre>
 */
@FunctionalInterface
public interface ViewModifier {

    /** Transform {@code content} into a new view (typically the styled body). */
    View body(View content);
}package dev.pathland.view;

import dev.pathland.view.signal.Signal;

import java.util.function.Consumer;

/**
 * Scopes an {@link EnvironmentKey} → value binding down a wrapped subtree
 * ({@code .modifiers(environmentBinding(e -> e.key(...).value(...)))}): the value
 * is active only while that subtree renders, and an outer binding is restored
 * afterward — nearest wins (spec DSL.md §5.5). Read it with
 * {@code Environment.value(key)}, which **always returns a signal**: a plain value is
 * wrapped in a constant signal; a signal value is returned as-is and stays reactive.
 * The modifier value is applied with {@code .modifiers(...)} like any other.
 */
public final class EnvironmentBinding implements ViewModifier {

    /** {@link EnvironmentBinding} values. */
    public static final class Config {

        private EnvironmentKey<?> key;
        private Object value;

        /** The environment key to bind. */
        public Config key(EnvironmentKey<?> key) {
            this.key = key;
            return this;
        }

        /** Bind a plain value (read back as a constant signal). */
        public Config value(Object value) {
            this.value = value;
            return this;
        }

        /** Bind a reactive value (the signal is returned as-is by {@link Environment#value}). */
        public Config value(Signal<?> value) {
            this.value = value;
            return this;
        }
    }

    private final EnvironmentKey<?> key;
    private final Object value;

    private EnvironmentBinding(Config config) {
        this.key = config.key;
        this.value = config.value;
    }

    /** Configure the binding ({@code environmentBinding(e -> e.key(...).value(...))}). */
    static EnvironmentBinding with(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new EnvironmentBinding(config);
    }

    @SuppressWarnings("unchecked")
    @Override
    public View body(View content) {
        return new EnvironmentView(content, (EnvironmentKey<Object>) key, value);
    }
}package dev.pathland.view;

import dev.pathland.view.emit.PathlandNode;

/**
 * A view scoped to an environment value: the binding is active only for this subtree's
 * render, so values below inherit it without threading a parameter through every
 * {@link View#render} call.
 */
final class EnvironmentView implements View {

    private final View content;
    private final EnvironmentKey<Object> key;
    private final Object value;

    EnvironmentView(View content, EnvironmentKey<Object> key, Object value) {
        this.content = content;
        this.key = key;
        this.value = value;
    }

    /** A scope wrapper for a typed {@link EnvironmentKey} → value binding. */
    @SuppressWarnings("unchecked")
    static <T> EnvironmentView of(View content, EnvironmentKey<T> key, T value) {
        return new EnvironmentView(content, (EnvironmentKey<Object>) key, value);
    }

    @Override
    public PathlandNode renderNode(Environment env) {
        EnvironmentValues scope = Environment.current().with(key, value);
        EnvironmentValues previous = Environment.current();
        Environment.within(scope);
        try {
            return content.renderNode(env);
        } finally {
            Environment.restore(previous);
        }
    }
}

