//! # pathland-view-native
//!
//! Native (non-WASM) projection of the Pathland flat world, exposed over both a
//! Rust API and a C ABI for foreign host languages (Swift / Java / C# / …).
//!
//! This is the **cross-language, zero-copy** path: a host links this crate as a
//! native library (or a `cdylib` and its `pathland_native_*` C functions), drives
//! the retained tree with the flat `builder`/`engine` operations, and reads
//! opcodes from the **shared-memory ring in place** — no serialization, no batch,
//! no WASM.
//!
//! The surface is the flat `builder`/`engine` world over a native shared-memory
//! transport.

use std::collections::{BTreeMap, HashMap};
use std::rc::Rc;

use pathland_engine::{Engine, MediaController, MediaControllerRef, SignalId, SignalValue};
use pathland_core::{component_type, property_id, MemoryLayout};
use pathland_core_transport::{
    DriverTransport, FrameSource, OpcodeBatch, RingTransport, TransportError,
};
use pathland_view::{component_type_id, Node};

mod capi;

/// A media controller transport slot (spec/MEDIA.md): the addressable signals of
/// a controller, so a flat host can read a report or write a command.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MediaControllerSlot {
    /// Play/pause command (`PLAYBACK_STATE`).
    Playing,
    /// Seek command (`MEDIA_POSITION`, seconds).
    Position,
    /// Volume command (`MEDIA_VOLUME`, 0..1).
    Volume,
    /// Mute command (`MEDIA_MUTED`).
    Muted,
    /// Loop-on-end command (`MEDIA_LOOP`).
    Loop,
    /// Playback rate command (`MEDIA_RATE`).
    Rate,
    /// Position report feed (`MEDIA_TIME_UPDATED`).
    Time,
    /// Duration report feed (`MEDIA_DURATION_CHANGED`).
    Duration,
    /// Volume report feed (`MEDIA_VOLUME_CHANGED`).
    VolumeReport,
}

impl MediaControllerSlot {
    /// The slot's signal id on `controller`.
    pub fn id_of(self, controller: &MediaController) -> SignalId {
        match self {
            MediaControllerSlot::Playing => controller.playing_signal().id(),
            MediaControllerSlot::Position => controller.position_signal().id(),
            MediaControllerSlot::Volume => controller.volume_signal().id(),
            MediaControllerSlot::Muted => controller.muted_signal().id(),
            MediaControllerSlot::Loop => controller.looping_signal().id(),
            MediaControllerSlot::Rate => controller.rate_signal().id(),
            MediaControllerSlot::Time => controller.time_signal().id(),
            MediaControllerSlot::Duration => controller.duration_signal().id(),
            MediaControllerSlot::VolumeReport => controller.volume_report_signal().id(),
        }
    }
}

/// A flat node in the host's retained tree (id → node).
#[derive(Clone)]
pub struct FlatNode {
    pub id: u32,
    pub view_component: pathland_view::Component,
    pub properties: BTreeMap<u16, u32>,
    /// A signal the node's text is bound to (overrides the component text).
    pub text_binding: Option<SignalId>,
    /// Property signals (propertyId → signal), overriding static properties.
    pub property_bindings: BTreeMap<u16, SignalId>,
    /// `STRING`-valued property signals (propertyId → signal), overriding the
    /// static value (e.g. a media controller's `MEDIA_SOURCE`).
    pub string_bindings: BTreeMap<u16, SignalId>,
    /// The media controller this node references (a host-side handle, spec/MEDIA.md):
    /// a marker node *is* the controller's node; a `VIDEO` node is one of its
    /// surfaces (`MEDIA_CONTROLLER_ID` is linked at materialization).
    pub media_controller: Option<u32>,
    pub parent: Option<u32>,
    pub children: Vec<u32>,
}

/// The native host: owns the retained tree, the diff engine, and the shared
/// zero-copy ring.
pub struct NativeHost {
    nodes: HashMap<u32, FlatNode>,
    engine: Engine,
    ring: RingTransport,
    /// Media controllers by host handle (spec/MEDIA.md). A controller is an
    /// engine-side state object; the flat world holds them so a host that links
    /// only this ABI can still author media.
    media_controllers: HashMap<u32, Rc<MediaController>>,
    next_media_controller: u32,
}

/// Safe, checked operations returning `()` (used by the C shim).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HostError {
    /// The operation referenced a missing node.
    NotFound,
}

impl NativeHost {
    /// Create a host with a fresh shared ring (default layout).
    pub fn new() -> Self {
        Self {
            nodes: HashMap::new(),
            engine: Engine::new(),
            ring: RingTransport::new(),
            media_controllers: HashMap::new(),
            next_media_controller: 1,
        }
    }


/// Create a string signal from a NUL-terminated UTF-8 C string.
#[no_mangle]
pub unsafe extern "C" fn pathland_native_signal_create_string(
    host: HostHandle,
    text: *const c_char,
) -> u32 {
    if text.is_null() {
        return u32::MAX;
    }
    let s = CStr::from_ptr(text).to_string_lossy().into_owned();
    as_host(host).create_signal(SignalValue::Str(s)).0
}

/// Set a float signal's value; re-emits only the nodes bound to it. Returns 1
/// if any opcode was written.
#[no_mangle]
pub unsafe extern "C" fn pathland_native_signal_set_f32(
    host: HostHandle,
    id: u32,
    value: f32,
) -> u8 {
    u8::from(as_host(host).set_signal(as_signal_id(id), SignalValue::F32(value)))
}

/// Set a raw u32 signal's value.
#[no_mangle]
pub unsafe extern "C" fn pathland_native_signal_set_u32(
    host: HostHandle,
    id: u32,
    value: u32,
) -> u8 {
    u8::from(as_host(host).set_signal(as_signal_id(id), SignalValue::U32(value)))
}

/// Set a boolean signal's value.
#[no_mangle]
pub unsafe extern "C" fn pathland_native_signal_set_bool(
    host: HostHandle,
    id: u32,
    value: u8,
) -> u8 {
    u8::from(as_host(host).set_signal(as_signal_id(id), SignalValue::Bool(value != 0)))
}

/// Set an enum signal's value.
#[no_mangle]
pub unsafe extern "C" fn pathland_native_signal_set_enum(
    host: HostHandle,
    id: u32,
    value: u8,
) -> u8 {
    u8::from(as_host(host).set_signal(as_signal_id(id), SignalValue::Enum(value)))
}

/// Set a string signal's value from a NUL-terminated UTF-8 C string.
#[no_mangle]
pub unsafe extern "C" fn pathland_native_signal_set_string(
    host: HostHandle,
    id: u32,
    text: *const c_char,
) -> u8 {
    if text.is_null() {
        return 0;
    }
    let s = CStr::from_ptr(text).to_string_lossy().into_owned();
    u8::from(as_host(host).set_signal(as_signal_id(id), SignalValue::Str(s)))
}

/// Bind a node's text to a signal (the signal's string value wins over static
/// text). Returns 1 if the node exists.
#[no_mangle]
pub unsafe extern "C" fn pathland_native_node_bind_text(
    host: HostHandle,
    node: u32,
    signal: u32,
) -> u8 {
    u8::from(as_host(host).bind_text(node, as_signal_id(signal)))
}

/// Bind a node's property to a signal. Returns 1 if the node exists.
#[no_mangle]
pub unsafe extern "C" fn pathland_native_node_bind_property(
    host: HostHandle,
    node: u32,
    prop: u32,
    signal: u32,
) -> u8 {
    u8::from(as_host(host).bind_property(node, prop as u16, as_signal_id(signal)))
}

// ---------------------------------------------------------------------------
// Media controllers (spec/MEDIA.md)
// ---------------------------------------------------------------------------

/// Create a media controller; returns its handle (0 on failure). The controller
/// owns its transport signals — reach them with
/// [`pathland_native_media_controller_signal`] and drive them with
/// `pathland_native_signal_set_*`.
#[no_mangle]
pub unsafe extern "C" fn pathland_native_media_controller_create(host: HostHandle) -> u32 {
    as_host(host).media_controller_create()
}

/// Set a controller's resource from a NUL-terminated UTF-8 C string. Returns 1
/// on success.
#[no_mangle]
pub unsafe extern "C" fn pathland_native_media_controller_source(
    host: HostHandle,
    handle: u32,
    source: *const c_char,
) -> u8 {
    if source.is_null() {
        return 0;
    }
    let source = CStr::from_ptr(source).to_string_lossy().into_owned();
    u8::from(as_host(host).media_controller_source(handle, &source))
}

/// A controller's transport signal for `slot` (0 = invalid). The slot codes are
/// the [`MediaControllerSlot`] order.
#[no_mangle]
pub unsafe extern "C" fn pathland_native_media_controller_signal(
    host: HostHandle,
    handle: u32,
    slot: u32,
) -> u32 {
    let slot = match slot {
        0 => MediaControllerSlot::Playing,
        1 => MediaControllerSlot::Position,
        2 => MediaControllerSlot::Volume,
        3 => MediaControllerSlot::Muted,
        4 => MediaControllerSlot::Loop,
        5 => MediaControllerSlot::Rate,
        6 => MediaControllerSlot::Time,
        7 => MediaControllerSlot::Duration,
        8 => MediaControllerSlot::VolumeReport,
        _ => return 0,
    };
    match as_host(host).media_controller_signal(handle, slot) {
        Some(id) => id.0,
        None => 0,
    }
}

/// Mark a node as referencing a media controller: a marker node (created as
/// `COMMENT`) becomes the controller's non-visual `MEDIA_CONTROLLER` node in
/// place; a `VIDEO` node becomes one of its surfaces. Returns 1 if the node and
/// handle exist.
#[no_mangle]
pub unsafe extern "C" fn pathland_native_node_media_controller(
    host: HostHandle,
    node: u32,
    handle: u32,
) -> u8 {
    u8::from(as_host(host).node_media_controller(node, handle))
}

/// Bind a node's **`STRING`**-valued property to a signal (e.g. a controller's
/// `MEDIA_SOURCE`). A change re-emits only that property. Returns 1 if the node
/// exists.
#[no_mangle]
pub unsafe extern "C" fn pathland_native_node_bind_string_property(
    host: HostHandle,
    node: u32,
    prop: u32,
    signal: u32,
) -> u8 {
    u8::from(as_host(host).bind_string_property(node, prop as u16, as_signal_id(signal)))
}

/// Bind a window/surface metadata field (`META::SET_WINDOW_METADATA`: 1 title,
/// 2 description, 3 locale) to a string signal. A change re-emits only that
/// field; renderers map it onto their own window chrome. Returns 1 for a
/// defined field.
#[no_mangle]
pub unsafe extern "C" fn pathland_native_window_metadata(
    host: HostHandle,
    field: u32,
    signal: u32,
) -> u8 {
    u8::from(as_host(host).bind_window_metadata(field as u16, as_signal_id(signal)))
}

