package dev.pathland.view;

import dev.pathland.view.signal.ConstantSignal;
import dev.pathland.view.signal.Signal;
import dev.pathland.view.signal.Signals;

import java.util.List;

/** Shared {@code GRID_TRACKS} wiring for {@code Grid}/{@code LazyVGrid}/{@code LazyHGrid}. */
final class GridTracks {

    private GridTracks() {}

    /** Join per-track sizes into the {@code GRID_TRACKS} STRING spec. */
    static String join(List<GridItem> tracks) {
        StringBuilder sb = new StringBuilder();
        for (GridItem t : tracks) {
            if (sb.length() > 0) {
                sb.append(',');
            }
            sb.append(t.token());
        }
        return sb.toString();
    }

    /** A (reactive) {@code GRID_TRACKS} string signal over the track list. */
    static Signal<String> signal(Signal<List<GridItem>> tracks) {
        if (tracks instanceof ConstantSignal) {
            return Signals.constant(join(tracks.get()));
        }
        return Signals.computed(() -> join(tracks.get()));
    }
}
package dev.pathland.view;

/** A single grid track spec ({@code GridItem} / Compose {@code GridCells}
 *  parity). Serializes to a `GRID_TRACKS` token — `flex`, `fixed:<points>`, or
 *  `adaptive:<points>` (spec/PRIMITIVES.md §grid model). */
public final class GridItem {

    private final String token;

    private GridItem(String token) {
        this.token = token;
    }

    /** An equal `1fr` share (what a bare count means). */
    public static GridItem flexible() {
        return new GridItem("flex");
    }

    /** Exactly {@code points} wide. */
    public static GridItem fixed(float points) {
        return new GridItem("fixed:" + fmt(points));
    }

    /** Auto-fit, at least {@code minPoints} wide (fit as many as fit). */
    public static GridItem adaptive(float minPoints) {
        return new GridItem("adaptive:" + fmt(minPoints));
    }

    private static String fmt(float v) {
        return v == Math.floor(v) && !Float.isInfinite(v) ? String.valueOf((long) v) : Float.toString(v);
    }

    /** The serialized `GRID_TRACKS` token. */
    public String token() {
        return token;
    }
}package dev.pathland.view;

import dev.pathland.view.emit.PathlandNode;

import java.util.function.Supplier;

/**
 * The component backing {@link View#of(Supplier)}: a Group-backed slot whose tracked
 * render reads the supplier (so its signals subscribe this component) and renders the
 * selected view as a child component slot.
 */
final class ReactiveSlotView implements View {

    private final Supplier<View> content;

    ReactiveSlotView(Supplier<View> content) {
        this.content = content;
    }

    @Override
    public PathlandNode renderNode(Environment env) {
        PathlandNode node = new PathlandNode(Components.VSTACK); // Group-backed slot
        View selected = content.get(); // tracked: a selector read re-renders this component
        if (selected != null) {
            node.children.add(selected.render(env));
        }
        return node;
    }
}
package dev.pathland.view;

import dev.pathland.view.emit.PathlandNode;

/** A view wrapped by {@code pointerEvents(mask)}: ORs the listener bits into {@code EVENT_LISTENERS}. */
final class PointerEventsView implements View {

    private final View content;
    private final int mask;

    PointerEventsView(View content, int mask) {
        this.content = content;
        this.mask = mask;
    }

    @Override
    public PathlandNode renderNode(Environment env) {
        PathlandNode node = content.renderNode(env);
        Object existing = node.properties.get(Properties.EVENT_LISTENERS);
        int current = existing instanceof Integer i ? i : 0;
        node.properties.put(Properties.EVENT_LISTENERS, current | mask);
        return node;
    }
}package dev.pathland.view;

import dev.pathland.view.emit.PathlandNode;

/**
 * A view wrapped by {@code onTapGesture}: declares the pointer down/up event listeners
 * and records the app-side action on the built node so the host can route a recognized
 * tap back to it.
 */
final class TapGestureView implements View {

    private final View content;
    private final Runnable action;

    TapGestureView(View content, Runnable action) {
        this.content = content;
        this.action = action;
    }

    @Override
    public PathlandNode renderNode(Environment env) {
        PathlandNode node = content.renderNode(env);
        Object existing = node.properties.get(Properties.EVENT_LISTENERS);
        int mask = existing instanceof Integer i ? i : 0;
        node.properties.put(
                Properties.EVENT_LISTENERS,
                mask | Commands.Listeners.POINTER_DOWN | Commands.Listeners.POINTER_UP);
        node.tapActions.add(action);
        return node;
    }
}package dev.pathland.view;

import dev.pathland.view.emit.PathlandNode;

import java.util.function.Consumer;

/**
 * A view wrapped by {@code onPathChange}: records the listener on the built node and
 * captures the active-path signal it should watch (the {@link Platform#ACTIVE_PATH}
 * environment value). The emitter registers a node-level effect that fires the
 * listeners when the signal changes, and destroys it when the subtree is replaced.
 */
final class PathChangeView implements View {

    private final View content;
    private final Consumer<String> listener;

    PathChangeView(View content, Consumer<String> listener) {
        this.content = content;
        this.listener = listener;
    }

    @Override
    public PathlandNode renderNode(Environment env) {
        PathlandNode node = content.renderNode(env);
        node.pathChangeListeners.add(listener);
        // The active-path signal provided by the host; null when not provided (inert).
        node.activePath = Environment.value(Platform.ACTIVE_PATH);
        return node;
    }
}

