     @Test
     void buffersDuringEditingAndCommitsOnRelease() {
         WritableSignal<Float> position = Signals.signal(0f);
         WritableSignal<Float> seekRequest = Signals.signal(0f);
         SeekControl seek = new SeekControl(position, seekRequest);

