         if (cached != null) {
             return cached;
         }
         synchronized (this) {
             if (baseCssName == null) {
                 try {
                     baseCssName = take(nativeRenderer.pathland_html_base_css_name());
                 } catch (LinkageError e) {
                     baseCssName = "";
                 }
             }
             return baseCssName;
         }
