         return ProxyIdMap.isProxyId(id) && ProxyIdMap.blockOf(id) == block;
     }

     // ── Lifecycle ───────────────────────────────────────────────────────────

     /** Connect to the origin (idempotent while open; re-invoked on reconnect). */
     public void start() {
         synchronized (lock) {
             if (closed) {
                 return;
             }
         }
         ProxyTransport t = transportFactory.create();
         synchronized (lock) {
             if (closed) {
                 return;
             }
             transport = t;
