     private void replacePendingMove(Event move) {
         for (int i = 0; i < pendingEvents.size(); i++) {
             Event e = pendingEvents.get(i);
             if (e.isPointerMove() && e.target() == move.target()) {
                 pendingEvents.set(i, move);
                 return;
             }
         }
         pendingEvents.add(move);
     }

