 /* ------------------------------------------------------------------------- */

 fun ProxyView(
     endpoint: String,
     route: String = "/",
     credential: String? = null,
 ): View = JProxyView.make { c ->
     c.endpoint(endpoint).route(route)
     if (credential != null) c.credential(credential)
 }.registerChild()

