-    private static void collectDuplicateIds(PathlandNode node, Set<Integer> seen, Set<Integer> duplicates) {
-        if (!seen.add(node.id)) {
-            duplicates.add(node.id);
-        }
-        for (PathlandNode child : node.children) {
-            collectDuplicateIds(child, seen, duplicates);
-        }
