-    private int freshIdFor(PathlandNode node) {
-        MediaController controller = node.mediaControllerRef;
-        if (controller != null && node.component == Components.MEDIA_CONTROLLER) {
-            Integer pinned = mediaControllerIds.get(controller);
-            if (pinned != null) {
