-            }
-
-            @Override
-            public void onDurationChanged(float seconds) {
-                c.duration().set(seconds);
-            }
-
-            @Override
-            public void onEnded() {
-                c.onEnded().run();
-            }
-
-            @Override
-            public void onVolumeChanged(float volume) {
