                 Event.textChanged(7, "Bob"),
                 Event.keyDown(3, 0x20, 0x01, Commands.Flags.KEY_REPEAT),
                 Event.keyUp(3, 0x20, 0x01),
                 Event.dateChanged(8, 20487, 43200000),
                 Event.scroll(9, 12f, -3f),
