     @Test
     void opcodeByteLayoutIs16BytesLittleEndian() {
         Opcode op = new Opcode(Categories.TREE, Commands.Tree.CREATE_NODE, 0, 1, Components.VSTACK, 0);
         byte[] bytes = op.toBytes();
         assertEquals(16, bytes.length);
         assertEquals(0x01, bytes[0] & 0xFF);
         assertEquals(0x01, bytes[1] & 0xFF);
         assertEquals(0x01, bytes[4] & 0xFF); // a=1
         assertEquals(0x10, bytes[8] & 0xFF); // b=0x0010 vstack
         assertEquals(op, Opcode.fromBytes(bytes));
     }

     @Test
     void tokenConformanceVectors17And18AreGoldenBytes() {
         // Vector 17: PARAMETER:SET_DESIGN_TOKEN (path="color.primary" arenaRef=0,
         // valueType=COLOR=0x07, value=0xFF0000FF) — spec/CONFORMANCE.md.
         Opcode setToken = new Opcode(
                 Categories.PARAMETER, Commands.Parameter.SET_DESIGN_TOKEN, 0, 0, ValueTypes.COLOR, 0xFF0000FF);
         assertArrayEquals(new byte[] {
                 0x02, 0x02, 0x00, 0x00,
                 0x00, 0x00, 0x00, 0x00,
                 0x07, 0x00, 0x00, 0x00,
                 (byte) 0xFF, 0x00, 0x00, (byte) 0xFF
         }, setToken.toBytes());

         // Vector 18: PARAMETER:SET_PROPERTY (id=1, COLOR=0x100A,
         // valueType=DESIGN_TOKEN=0x08, arenaRef=0) — spec/CONFORMANCE.md.
         Opcode tokenRef = new Opcode(
                 Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, 1,
                 (ValueTypes.DESIGN_TOKEN << 16) | Properties.COLOR, 0);
         assertArrayEquals(new byte[] {
                 0x02, 0x01, 0x00, 0x00,
                 0x01, 0x00, 0x00, 0x00,
                 0x0A, 0x10, 0x08, 0x00,
                 0x00, 0x00, 0x00, 0x00
         }, tokenRef.toBytes());
     }

     @Test
     void frameCodecCarriesDesignTokenRef() {
         FrameOpcodeSink sink = new FrameOpcodeSink();
         Emitter emitter = new Emitter(sink);
         emitter.mount(Text.make(t -> t.text("x"))
                 .modifiers(foregroundStyle(f -> f.color(Color.token("color.primary")))),
                 Environment.DEFAULT);

         byte[] wire = FrameCodec.encodeFrame(sink.frame());
         ProtocolFrame decoded = FrameCodec.decodeFrame(wire);

         boolean sawRef = false;
         for (Opcode op : decoded.opcodes()) {
             if (op.category() == Categories.PARAMETER && op.command() == Commands.Parameter.SET_PROPERTY
                     && (op.b() & 0xFFFF) == Properties.COLOR) {
                 assertEquals(ValueTypes.DESIGN_TOKEN, (op.b() >>> 16) & 0xFF);
                 assertEquals("color.primary", decoded.stringAt(op.c()));
                 sawRef = true;
             }
         }
         assertTrue(sawRef, "DESIGN_TOKEN property ref round-trips through the codec");
     }

     @Test
     void themeEmitsGlobalDesignTokenOverrides() {
         FrameOpcodeSink sink = new FrameOpcodeSink();
         Theme light = new Theme()
                 .color("color.primary", 0xFF2563EB)
                 .f32("space.base", 4.0f)
                 .string("font.body.family", "Inter");
         Theme dark = new Theme()
                 .color("color.primary", 0xFF60A5FA)
                 .f32("space.base", 4.0f);
         new AdaptiveTheme(light, dark).emit(sink);

         ProtocolFrame frame = sink.frame();
         boolean sawLight = false, sawDark = false, sawF32 = false, sawString = false, sawDarkF32 = false;
         for (Opcode op : frame.opcodes()) {
             assertEquals(Categories.PARAMETER, op.category());
             assertEquals(Commands.Parameter.SET_DESIGN_TOKEN, op.command());
             switch (op.b()) {
                 case ValueTypes.COLOR -> {
                     if ("color.primary".equals(frame.stringAt(op.a()))) {
                         sawLight = true;
                         assertEquals(0xFF2563EB, op.c(), "light primary");
                     } else {
                         sawDark = true;
                         assertEquals("dark.color.primary", frame.stringAt(op.a()));
                         assertEquals(0xFF60A5FA, op.c(), "dark primary");
                     }
                 }
                 case ValueTypes.F32 -> {
                     String path = frame.stringAt(op.a());
                     if ("space.base".equals(path)) {
                         sawF32 = true;
                         assertEquals(4.0f, Float.intBitsToFloat(op.c()), "light space.base");
                     } else {
                         sawDarkF32 = true;
                         assertEquals("dark.space.base", path);
                     }
                 }
                 case ValueTypes.STRING -> {
                     sawString = true;
                     assertEquals("font.body.family", frame.stringAt(op.a()));
                     assertEquals("Inter", frame.stringAt(op.c()));
                 }
                 default -> { }
             }
         }
         assertTrue(sawLight, "light color override emitted unprefixed");
         assertTrue(sawDark, "dark color override emitted with the dark. prefix");
         assertTrue(sawF32, "light f32 override emitted");
         assertTrue(sawDarkF32, "dark f32 override emitted with the dark. prefix");
         assertTrue(sawString, "STRING override emitted");

         // Overrides ride the network batch too.
         ProtocolFrame decoded = FrameCodec.decodeFrame(FrameCodec.encodeFrame(frame));
         assertEquals(frame.opcodes(), decoded.opcodes());
     }

     @Test
     void aBareThemeEmitsLightOverridesWithoutPrefix() {
         // A single Theme (ThemeData) mounts as light-only overrides.
         FrameOpcodeSink sink = new FrameOpcodeSink();
         new Theme().color("color.accent", 0xFF123456).emit(sink);
         ProtocolFrame frame = sink.frame();
         assertEquals(1, frame.opcodes().size());
         Opcode only = frame.opcodes().get(0);
         assertEquals("color.accent", frame.stringAt(only.a()));
         assertEquals(0xFF123456, only.c());
     }

     @Test
     void lengthTokenEmitsDesignTokenForSpacingAndFontSize() {
         FrameOpcodeSink sink = new FrameOpcodeSink();
         Emitter emitter = new Emitter(sink);
         emitter.mount(
                 VStack.make(v -> v.spacing(Length.token("space.2")))
                         .children(Text.make("x").modifiers(
                                 padding(Length.token("space.3")),
                                 fontSize(Length.token("font.body.size")))),
                 Environment.DEFAULT);

         ProtocolFrame frame = sink.frame();
         List<Opcode> tokens = frame.opcodes().stream()
                 .filter(o -> o.category() == Categories.PARAMETER
                         && o.command() == Commands.Parameter.SET_PROPERTY
                         && ((o.b() >>> 16) & 0xff) == ValueTypes.DESIGN_TOKEN)
                 .toList();
         assertEquals(3, tokens.size(), "spacing + padding + font size token refs");
         assertTrue(tokens.stream().anyMatch(o -> tokenPath(frame, o).equals("space.2")));
         assertTrue(tokens.stream().anyMatch(o -> tokenPath(frame, o).equals("space.3")));
         assertTrue(tokens.stream().anyMatch(o -> tokenPath(frame, o).equals("font.body.size")));
     }

     private static String tokenPath(ProtocolFrame frame, Opcode op) {
         return frame.stringAt(op.c());
     }

     @Test
     void runtimeThemeReplacementEmitsResetThenTheOverrides() {
         FrameOpcodeSink sink = new FrameOpcodeSink();
         Emitter emitter = new Emitter(sink);
         emitter.mount(Text.make("x"), Environment.DEFAULT);

         emitter.replaceTheme(new Theme().color("color.primary", 0xFF60A5FA));
         ProtocolFrame frame = sink.frame();
         assertEquals(1, countOps(frame, Categories.META, Commands.Meta.RESET_THEME));
         assertEquals(1, countOps(frame, Categories.PARAMETER, Commands.Parameter.SET_DESIGN_TOKEN));
         Opcode override = frame.opcodes().stream()
                 .filter(o -> o.command() == Commands.Parameter.SET_DESIGN_TOKEN)
                 .findFirst().orElseThrow();
         assertEquals("color.primary", frame.stringAt(override.a()));
         assertEquals(0xFF60A5FA, override.c());
     }

     @Test
     void runtimeSchemeOverrideEmitsMetaCommand() {
         FrameOpcodeSink sink = new FrameOpcodeSink();
         Emitter emitter = new Emitter(sink);
         emitter.mount(Text.make("x"), Environment.DEFAULT);

         emitter.setColorScheme(ThemeMode.DARK);
         ProtocolFrame frame = sink.frame();
         assertEquals(1, countOps(frame, Categories.META, Commands.Meta.SET_COLOR_SCHEME));
         Opcode op = frame.opcodes().get(0);
         assertEquals(2, op.a(), "A = DARK mode");
     }

     @Test
     void windowMetadataMountsAndReEmitsOnlyTheChangedField() {
         FrameOpcodeSink sink = new FrameOpcodeSink();
         Emitter emitter = new Emitter(sink);
         WritableSignal<String> title = Signals.signal("Library");
         WritableSignal<String> description = Signals.signal("8 songs");
         View root = VStack.children(Text.make("body"))
                 .modifiers(windowMetadata(w -> w
                         .title(title)
                         .description(description)
                         .locale("en")));

         emitter.mount(root, Environment.DEFAULT);
         ProtocolFrame mount = sink.frame();
         assertEquals(3, countOps(mount, Categories.META, Commands.Meta.SET_WINDOW_METADATA),
                 "title + description + locale");
         assertEquals("Library", windowValue(mount, Commands.WindowFields.TITLE));

         title.set("Now Playing");
         ProtocolFrame delta = sink.frame();
         assertEquals(1, countOps(delta, Categories.META, Commands.Meta.SET_WINDOW_METADATA),
                 "one opcode for the changed title");
         Opcode op = delta.opcodes().get(0);
         assertEquals(Commands.WindowFields.TITLE, op.a());
         assertEquals("Now Playing", delta.stringAt(op.b()));

         // Unchanged value → no new frame/opcodes.
         int produced = sink.framesProduced();
         title.set("Now Playing");
         assertEquals(produced, sink.framesProduced(), "unchanged metadata emits no frame");
     }

     @Test
     void windowMetadataFullSnapshotReEmitsEveryField() {
         FrameOpcodeSink sink = new FrameOpcodeSink();
         Emitter emitter = new Emitter(sink);
         emitter.mount(VStack.children(Text.make("body"))
                 .modifiers(windowMetadata(w -> w.title("Library").locale("en"))), Environment.DEFAULT);
         emitter.renderFull();
         ProtocolFrame frame = sink.frame();
         // Force re-sends every field; an unset field is sent as a clear.
         assertEquals(3, countOps(frame, Categories.META, Commands.Meta.SET_WINDOW_METADATA));
     }

     private static String windowValue(ProtocolFrame frame, int field) {
         Opcode op = frame.opcodes().stream()
                 .filter(o -> o.category() == Categories.META
                         && o.command() == Commands.Meta.SET_WINDOW_METADATA
                         && o.a() == field)
                 .findFirst().orElseThrow();
         return frame.stringAt(op.b());
     }
 }
