         // The content still attaches as the single child.
         assertTrue(frame.opcodes().stream()
                         .anyMatch(o -> o.category() == Categories.TREE
                                 && o.command() == Commands.Tree.INSERT_CHILD && o.a() == id),
                 "the content child is attached");
     }
 }

