/**
 * Marker for the DSL's style values (style protocols). A style supplies a
 * control's or view's content via {@code makeBody(Configuration)} — it never owns the
 * control's component or its interaction (spec DSL.md §5.7). A style **is** a
 * {@link ViewModifier} value ({@code .modifiers(MyButtonStyle)}): applying it scopes
 * the matching environment key down the wrapped subtree, nearest-wins.
 */
public interface Style extends ViewModifier {
}
package dev.pathland.view;

/**
 * A button style ({@code ButtonStyle}). A style turns a button's
 * {@link ButtonStyle.Configuration} (its label) into the button's <em>content</em>
 * view. The {@link Button} control owns the native {@code BUTTON} node and wires the
 * action, so a style only decorates the label (spec DSL.md §5.7). Styles are injected
 * down the tree via {@link View#buttonStyle(ButtonStyle)}.
 */
public interface ButtonStyle extends Style {

    /** Build the styled button content for {@code config}. */
    View makeBody(Configuration config);

    /** Scopes this style down the wrapped subtree ({@code .modifiers(ButtonStyle)}). */
    @Override
    default View body(View content) {
        return EnvironmentView.of(content, Environment.BUTTON_STYLE, this);
    }

    /**
     * The configuration of the button being styled: its label. The {@link Button}
     * control attaches the returned content as the button node's child, and wires the
     * action on the button node. A style therefore never attaches the tap gesture.
     */
    record Configuration(View label) {}
}
package dev.pathland.view;

/**
 * The presentation of a {@link Label} ({@code LabelStyle}). A style turns a
 * label's {@link Configuration} (its title and icon parts) into the label's content
 * view — it decides which parts render and how they are arranged.
 *
 * <p>DSL-only control flow: the style shapes the emitted child tree, which <em>is</em>
 * the wire surface; there is never a style property. Scoped down a subtree with
 * the style value itself as a modifier ({@code .modifiers(LabelStyle)}) via the generic
 * environment ({@link Environment#LABEL_STYLE}), nearest-wins (spec DSL.md §5.7).
 * Built-ins: {@link DefaultLabelStyle} (title + icon), {@link TitleOnlyLabelStyle},
 * {@link IconOnlyLabelStyle}.
 */
public interface LabelStyle extends Style {

    /** Build the styled label content for {@code config}. */
    View makeBody(Configuration config);

    /** Scopes this style down the wrapped subtree ({@code .modifiers(LabelStyle)}). */
    @Override
    default View body(View content) {
        return EnvironmentView.of(content, Environment.LABEL_STYLE, this);
    }

    /**
     * The parts of the label being styled. A part is {@code null} when it is absent
     * (no title text / no icon) — the built-in styles omit an absent part, and a custom
     * style should check {@link #hasTitle()}/{@link #hasIcon()} before styling it.
     *
     * <p>Delta: the {@code LabelStyleConfiguration.title}/{@code .icon}
     * are always-present views (empty when the part is absent); Pathland passes
     * {@code null} instead, so an absent part is easy to omit.
     */
    record Configuration(View title, View icon) {

        /** Whether the label has a title part. */
        public boolean hasTitle() {
            return title != null;
        }

        /** Whether the label has an icon part. */
        public boolean hasIcon() {
            return icon != null;
        }
    }
}
