     private static HtmlRenderer renderer() {
         try {
             return HtmlRenderer.instance();
         } catch (Throwable t) {
             Assumptions.assumeTrue(false,
                     "libpathland_render_html unavailable on java.library.path; shim test skipped: " + t);
             return null;
