+        AtomicInteger runs = new AtomicInteger();
+        WritableSignal<Integer> a = Signals.signal(1);
+        Signal<Integer> b = Signals.computed(() -> {
+            runs.incrementAndGet();
+            return a.get() * 10;
+        });
+        assertEquals(10, b.get());
+        a.set(1); // equal -> no propagation
+        assertEquals(10, b.get());
