/// Emit the full `constants.ts`.
pub fn emit_constants_ts() -> String {
    let mut out = String::new();
    out.push_str(
        "// Generated by `cargo run -p pathland-ts-codegen` (lib/rust). Do not edit.\n\
         // Wire constants are bound to `pathland_core::constants`; enum codes mirror\n\
         // spec/MODIFIERS.md + spec/OPCODE.md. Regenerate with `npm run regen`.\n\n\
         // Batch header\n",
    );
    write_consts(&mut out, "", &[
        ("MAGIC", format!("{:#x}", 0x504c504cu32)),
        ("VERSION", "1".into()),
        ("HEADER_SIZE", "16".into()),
        ("OPCODE_SIZE", "16".into()),
        ("FLAG_HOST_TO_GUEST", "0x0001".into()),
    ]);
    out.push_str("\n// Categories\n");
    write_consts(&mut out, "CAT_", &[
        ("TREE", fmt_u8(category::TREE)),
        ("PARAMETER", fmt_u8(category::PARAMETER)),
        ("EVENT", fmt_u8(category::EVENT)),
        ("META", fmt_u8(category::META)),
    ]);
    out.push_str("\n// TREE commands\n");
    write_consts(&mut out, "CMD_", &[
        ("CREATE_NODE", fmt_u8(tree::CREATE_NODE)),
        ("DELETE_NODE", fmt_u8(tree::DELETE_NODE)),
        ("INSERT_CHILD", fmt_u8(tree::INSERT_CHILD)),
        ("REMOVE_CHILD", fmt_u8(tree::REMOVE_CHILD)),
        ("MOVE_CHILD", fmt_u8(tree::MOVE_CHILD)),
    ]);
    out.push_str("\n// PARAMETER commands\n");
    write_consts(&mut out, "CMD_", &[
        ("SET_PROPERTY", fmt_u8(parameter::SET_PROPERTY)),
        ("SET_DESIGN_TOKEN", fmt_u8(parameter::SET_DESIGN_TOKEN)),
        ("SET_TEXT", fmt_u8(parameter::SET_TEXT)),
        ("SET_DATE", fmt_u8(parameter::SET_DATE)),
    ]);
    out.push_str("\n// META commands\n");
    write_consts(&mut out, "CMD_", &[
        ("RESET", fmt_u8(meta::RESET)),
        ("ENVIRONMENT", fmt_u8(meta::ENVIRONMENT)),
        ("RESYNC", fmt_u8(meta::RESYNC)),
        ("PING", fmt_u8(meta::PING)),
        ("PONG", fmt_u8(meta::PONG)),
        ("SET_COLOR_SCHEME", fmt_u8(meta::SET_COLOR_SCHEME)),
        ("RESET_THEME", fmt_u8(meta::RESET_THEME)),
        ("SET_WINDOW_METADATA", fmt_u8(meta::SET_WINDOW_METADATA)),
    ]);
    out.push_str("\n// META::SET_COLOR_SCHEME modes\n");
    write_consts(&mut out, "COLOR_SCHEME_", &[
        ("PLATFORM", fmt_u32(color_scheme_mode::PLATFORM)),
        ("LIGHT", fmt_u32(color_scheme_mode::LIGHT)),
        ("DARK", fmt_u32(color_scheme_mode::DARK)),
