fn emit_manifest() -> String {
    let mut out = String::new();
    out.push_str(
        "# Generated by `cargo run -p pathland-protocol-manifest` (lib/rust). Do not edit.\n\
         # Target-neutral Pathland wire protocol. Columns: kind, group, name, value.\n\
         # Values are hex integers, decimal floats, or symbolic value-type names.\n\
         #\n\
         # Consumers own their target-language representation and formatting.\n\n",
    );

    for (name, value) in [
        ("TREE", category::TREE),
        ("PARAMETER", category::PARAMETER),
        ("EVENT", category::EVENT),
        ("META", category::META),
    ] {
        row(&mut out, "category", "", name, &hex_u8(value));
    }
    out.push('\n');

    for (name, value) in [
        ("TEXT", component_type::TEXT),
        ("IMAGE", component_type::IMAGE),
        ("COLOR", component_type::COLOR),
        ("SHAPE", component_type::SHAPE),
        ("DIVIDER", component_type::DIVIDER),
        ("SPACER", component_type::SPACER),
        ("PROGRESS_VIEW", component_type::PROGRESS_VIEW),
        ("GAUGE", component_type::GAUGE),
        ("VIDEO", component_type::VIDEO),
        ("ICON", component_type::ICON),
        ("VSTACK", component_type::VSTACK),
        ("HSTACK", component_type::HSTACK),
        ("ZSTACK", component_type::ZSTACK),
        ("GRID", component_type::GRID),
        ("SCROLLVIEW", component_type::SCROLLVIEW),
        ("LAZY_VGRID", component_type::LAZY_VGRID),
        ("LAZY_HGRID", component_type::LAZY_HGRID),
        ("SIZE_THAT_FITS", component_type::SIZE_THAT_FITS),
        ("LAZY_VSTACK", component_type::LAZY_VSTACK),
        ("LAZY_HSTACK", component_type::LAZY_HSTACK),
        ("GRID_ROW", component_type::GRID_ROW),
        ("PROXY_VIEW", component_type::PROXY_VIEW),
        ("BUTTON", component_type::BUTTON),
        ("TEXT_FIELD", component_type::TEXT_FIELD),
        ("TEXT_EDITOR", component_type::TEXT_EDITOR),
        ("TOGGLE", component_type::TOGGLE),
        ("SLIDER", component_type::SLIDER),
        ("STEPPER", component_type::STEPPER),
        ("DATE_PICKER", component_type::DATE_PICKER),
        ("PICKER", component_type::PICKER),
        ("MENU", component_type::MENU),
        ("COLOR_PICKER", component_type::COLOR_PICKER),
        ("MEDIA_CONTROLLER", component_type::MEDIA_CONTROLLER),
        ("COMMENT", component_type::COMMENT),
    ] {
        row(&mut out, "component", "", name, &hex_u16(value));
    }
    out.push('\n');

    for (name, value) in [
        ("CREATE_NODE", tree::CREATE_NODE),
        ("DELETE_NODE", tree::DELETE_NODE),
        ("INSERT_CHILD", tree::INSERT_CHILD),
        ("REMOVE_CHILD", tree::REMOVE_CHILD),
        ("MOVE_CHILD", tree::MOVE_CHILD),
    ] {
        row(&mut out, "command", "Tree", name, &hex_u8(value));
    }
    for (name, value) in [
        ("SET_PROPERTY", parameter::SET_PROPERTY),
        ("SET_DESIGN_TOKEN", parameter::SET_DESIGN_TOKEN),
        ("SET_TEXT", parameter::SET_TEXT),
        ("SET_DATE", parameter::SET_DATE),
    ] {
        row(&mut out, "command", "Parameter", name, &hex_u8(value));
    }
    for (name, value) in [
        ("POINTER_DOWN", event::POINTER_DOWN),
        ("POINTER_MOVE", event::POINTER_MOVE),
        ("POINTER_UP", event::POINTER_UP),
        ("KEY_DOWN", event::KEY_DOWN),
        ("KEY_UP", event::KEY_UP),
        ("VALUE_CHANGED", event::VALUE_CHANGED),
        ("TEXT_CHANGED", event::TEXT_CHANGED),
        ("FOCUS_CHANGED", event::FOCUS_CHANGED),
        ("EDITING_CHANGED", event::EDITING_CHANGED),
        ("SUBMIT", event::SUBMIT),
        ("SCROLL", event::SCROLL),
        ("WHEEL", event::WHEEL),
        ("DATE_CHANGED", event::DATE_CHANGED),
        ("NAVIGATE", event::NAVIGATE),
        ("MEDIA_PLAY_STATE_CHANGED", event::MEDIA_PLAY_STATE_CHANGED),
        ("MEDIA_TIME_UPDATED", event::MEDIA_TIME_UPDATED),
        ("MEDIA_ENDED", event::MEDIA_ENDED),
        ("MEDIA_VOLUME_CHANGED", event::MEDIA_VOLUME_CHANGED),
        ("FIT_CHANGED", event::FIT_CHANGED),
        ("MEDIA_DURATION_CHANGED", event::MEDIA_DURATION_CHANGED),
    ] {
        row(&mut out, "command", "Event", name, &hex_u8(value));
    }
    for (name, value) in [
        ("RESET", meta::RESET),
        ("ENVIRONMENT", meta::ENVIRONMENT),
        ("RESYNC", meta::RESYNC),
        ("PING", meta::PING),
        ("PONG", meta::PONG),
        ("SET_COLOR_SCHEME", meta::SET_COLOR_SCHEME),
        ("RESET_THEME", meta::RESET_THEME),
        ("SET_WINDOW_METADATA", meta::SET_WINDOW_METADATA),
    ] {
        row(&mut out, "command", "Meta", name, &hex_u8(value));
    }
    out.push('\n');

    for (name, value) in [
        ("TITLE", window_field::TITLE),
        ("DESCRIPTION", window_field::DESCRIPTION),
        ("LOCALE", window_field::LOCALE),
    ] {
        row(&mut out, "field", "WindowFields", name, &hex_u16(value));
    }
    for (name, value) in [
        ("PLATFORM", color_scheme_mode::PLATFORM),
        ("LIGHT", color_scheme_mode::LIGHT),
        ("DARK", color_scheme_mode::DARK),
    ] {
        row(
            &mut out,
            "field",
            "ColorSchemeMode",
            name,
            &hex_u32(value),
        );
    }
    for (name, value) in [
        ("VIEWPORT_WIDTH", environment::VIEWPORT_WIDTH),
        ("VIEWPORT_HEIGHT", environment::VIEWPORT_HEIGHT),
        ("ROUTE", environment::ROUTE),
    ] {
        row(&mut out, "field", "Environment", name, &hex_u16(value));
    }
    out.push('\n');

    for (name, value) in [
        ("POINTER_SECONDARY", flag::POINTER_SECONDARY),
        ("HOVER_ENTER", flag::HOVER_ENTER),
        ("HOVER_LEAVE", flag::HOVER_LEAVE),
        ("KEY_REPEAT", flag::KEY_REPEAT),
        ("NAVIGATE_URL", flag::NAVIGATE_URL),
    ] {
        row(&mut out, "flag", "Flags", name, &hex_u16(value));
    }
    out.push('\n');

    for (name, value) in [
        ("POINTER_DOWN", listener::POINTER_DOWN),
        ("POINTER_MOVE", listener::POINTER_MOVE),
        ("POINTER_UP", listener::POINTER_UP),
        ("KEY_DOWN", listener::KEY_DOWN),
        ("KEY_UP", listener::KEY_UP),
        ("FOCUS", listener::FOCUS),
        ("EDITING", listener::EDITING),
        ("SUBMIT", listener::SUBMIT),
        ("SCROLL", listener::SCROLL),
        ("WHEEL", listener::WHEEL),
        ("POINTER", listener::POINTER),
    ] {
        row(&mut out, "listener", "Listeners", name, &hex_u32(value));
    }
    out.push('\n');

    for (name, value) in [("FILL", size::FILL), ("HUG_CONTENT", size::HUG_CONTENT)] {
        row(&mut out, "size", "Size", name, &value.to_string());
    }
    out.push('\n');

    for (name, value) in [
        ("U8", value_type::U8),
        ("U32", value_type::U32),
        ("I32", value_type::I32),
        ("F32", value_type::F32),
        ("STRING", value_type::STRING),
        ("ENUM", value_type::ENUM),
        ("COLOR", value_type::COLOR),
        ("DESIGN_TOKEN", value_type::DESIGN_TOKEN),
        ("LIST", value_type::LIST),
    ] {
        row(&mut out, "value_type", "", name, &hex_u8(value));
    }
    out.push('\n');

    for (name, value) in properties() {
        row(&mut out, "property", "", name, &hex_u16(value));
    }
    out.push('\n');

    for (name, value) in properties() {
        row(
            &mut out,
            "property_value_type",
            "",
            name,
            value_type_name(value_type_for(value)),
        );
    }

    out
}

fn main() -> io::Result<()> {
    let path = manifest_path();
    std::fs::write(&path, emit_manifest())?;
    println!("wrote {}", path.display());
    Ok(())
}

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Generates the JVM engine's protocol constant classes from the neutral
 * {@code spec/protocol.tsv} manifest.
 *
 * <p>The Rust side only emits data. This Java tool owns the Java package, class
 * names, formatting, and type mapping. Run it through
 * {@code scripts/regen-java-protocol.sh}, not by hand.
 *
 * <pre>{@code
 * java lib/java/tools/protocol-codegen/ProtocolCodegen.java \
 *     spec/protocol.tsv \
 *     lib/java/pathland-view-core/src/main/java
 * }</pre>
 */
public final class ProtocolCodegen {

    private static final String PACKAGE = "dev.pathland.view.core.protocol";

    private ProtocolCodegen() {
    }

    record Row(String kind, String group, String name, String value) {
    }

    public static void main(String[] args) throws IOException {
        if (args.length != 2) {
            System.err.println("usage: ProtocolCodegen <protocol.tsv> <java-source-root>");
            System.exit(2);
        }
        Path manifest = Path.of(args[0]);
        Path javaRoot = Path.of(args[1]);
        List<Row> rows = readRows(manifest);
        Path protocolDir = javaRoot.resolve(PACKAGE.replace('.', '/'));
        Files.createDirectories(protocolDir);

        write(protocolDir.resolve("Categories.java"), emitCategories(rows));
        write(protocolDir.resolve("Components.java"), emitComponents(rows));
        write(protocolDir.resolve("Commands.java"), emitCommands(rows));
        write(protocolDir.resolve("Properties.java"), emitProperties(rows));
        write(protocolDir.resolve("ValueTypes.java"), emitValueTypes(rows));
    }

    private static List<Row> readRows(Path manifest) throws IOException {
        List<Row> rows = new ArrayList<>();
        for (String line : Files.readAllLines(manifest, StandardCharsets.UTF_8)) {
            if (line.isBlank() || line.startsWith("#")) {
                continue;
            }
            String[] parts = line.split("\t", -1);
            if (parts.length != 4) {
                throw new IllegalArgumentException("bad manifest row: " + line);
            }
            rows.add(new Row(parts[0], parts[1], parts[2], parts[3]));
        }
        return rows;
    }

    private static List<Row> ofKind(List<Row> rows, String kind) {
        return rows.stream().filter(r -> r.kind().equals(kind)).toList();
    }

    private static Map<String, List<Row>> byGroup(List<Row> rows, String kind) {
        Map<String, List<Row>> groups = new LinkedHashMap<>();
        for (Row row : rows) {
            if (row.kind().equals(kind)) {
                groups.computeIfAbsent(row.group(), ignored -> new ArrayList<>()).add(row);
            }
        }
        return groups;
    }

    private static String emitCategories(List<Row> rows) {
        return simpleClass(
                "Categories",
                "Opcode categories (spec/OPCODE.md).",
                ofKind(rows, "category"));
    }

    private static String emitComponents(List<Row> rows) {
        return simpleClass(
                "Components",
                "Protocol component type ids (spec/PRIMITIVES.md).",
                ofKind(rows, "component"));
    }

    private static String emitProperties(List<Row> rows) {
        return simpleClass(
                "Properties",
                "Protocol property ids (spec/MODIFIERS.md, spec/OPCODE.md).",
                ofKind(rows, "property"));
    }

    private static String simpleClass(String name, String doc, List<Row> rows) {
        StringBuilder out = new StringBuilder();
        header(out);
        out.append("package ").append(PACKAGE).append(";\n\n");
        out.append("/** ").append(doc).append(" */\n");
        out.append("public final class ").append(name).append(" {\n\n");
        for (Row row : rows) {
            out.append("    public static final int ")
                    .append(row.name())
                    .append(" = ")
                    .append(row.value())
                    .append(";\n");
        }
        out.append("\n    private ").append(name).append("() {}\n");
        out.append("}\n");
        return out.toString();
    }

    private static String emitCommands(List<Row> rows) {
        StringBuilder out = new StringBuilder();
        header(out);
        out.append("package ").append(PACKAGE).append(";\n\n");
        out.append("/** Commands, field ids, flags, and listener bits per category. */\n");
        out.append("public final class Commands {\n\n");
        out.append("    private Commands() {}\n");

        Map<String, List<Row>> commandGroups = byGroup(rows, "command");
        Map<String, List<Row>> fieldGroups = byGroup(rows, "field");
        Map<String, List<Row>> flagGroups = byGroup(rows, "flag");
        Map<String, List<Row>> listenerGroups = byGroup(rows, "listener");
        Map<String, List<Row>> sizeGroups = byGroup(rows, "size");

        appendGroups(out, "Commands", commandGroups, false);
        appendGroups(out, "Field ids", fieldGroups, false);
        appendGroups(out, "Flags", flagGroups, false);
        appendGroups(out, "Listener bits", listenerGroups, false);
        appendGroups(out, "Sizes", sizeGroups, true);

        out.append("}\n");
        return out.toString();
    }

    private static void appendGroups(
            StringBuilder out,
            String doc,
            Map<String, List<Row>> groups,
            boolean floats) {
        for (Map.Entry<String, List<Row>> entry : groups.entrySet()) {
            out.append("\n    /** ").append(doc).append(": ").append(entry.getKey()).append(". */\n");
            out.append("    public static final class ").append(entry.getKey()).append(" {\n");
            for (Row row : entry.getValue()) {
                String type = floats ? "float" : "int";
                String value = floats ? row.value() + "f" : row.value();
                out.append("        public static final ")
                        .append(type)
                        .append(' ')
                        .append(row.name())
                        .append(" = ")
                        .append(value)
                        .append(";\n");
            }
            out.append("\n        private ").append(entry.getKey()).append("() {}\n");
            out.append("    }\n");
        }
    }

    private static String emitValueTypes(List<Row> rows) {
        StringBuilder out = new StringBuilder();
        header(out);
        out.append("package ").append(PACKAGE).append(";\n\n");
        out.append("/** Value types for PARAMETER::SET_PROPERTY (spec/OPCODE.md). */\n");
        out.append("public final class ValueTypes {\n\n");
        for (Row row : ofKind(rows, "value_type")) {
            out.append("    public static final int ")
                    .append(row.name())
                    .append(" = ")
                    .append(row.value())
                    .append(";\n");
        }

        out.append("\n    /** The protocol value type for a property id (from spec/protocol.tsv). */\n");
        out.append("    public static int forProperty(int prop) {\n");
        out.append("        return switch (prop) {\n");

        Map<String, List<String>> byType = new LinkedHashMap<>();
        for (Row row : ofKind(rows, "property_value_type")) {
            if (!row.value().equals("F32")) {
                byType.computeIfAbsent(row.value(), ignored -> new ArrayList<>()).add(row.name());
            }
        }
        for (Map.Entry<String, List<String>> entry : byType.entrySet()) {
            List<String> names = entry.getValue().stream()
                    .map(name -> "Properties." + name)
                    .toList();
            out.append("            case ")
                    .append(String.join(", ", names))
                    .append(" -> ")
                    .append(entry.getKey())
                    .append(";\n");
        }
        out.append("            default -> F32;\n");
        out.append("        };\n");
        out.append("    }\n\n");
        out.append("    private ValueTypes() {}\n");
        out.append("}\n");
        return out.toString();
    }

    private static void header(StringBuilder out) {
        out.append("// Generated from spec/protocol.tsv by scripts/regen-java-protocol.sh. Do not edit.\n");
        out.append("// Edit the canonical Rust constants, then regenerate the manifest and this mirror.\n\n");
    }

    private static void write(Path path, String content) throws IOException {
        Files.writeString(path, content, StandardCharsets.UTF_8);
        System.out.println("wrote " + path);
    }
}

