     /// dragged to a point on its track); the guest/app writes it into its state.
     pub const VALUE_CHANGED: u8 = 0x06;
     /// `A=targetId, B=string offset` — a text field's value changed (host →
     /// guest). The new text lives in the batch's string section, referenced by
     /// the *relative* offset in `B` (the same convention as `PARAMETER::SET_TEXT`).
     pub const TEXT_CHANGED: u8 = 0x07;
     /// **Draft.** `A=targetId, B=focused (0/1)` — a node gained/lost focus.
     pub const FOCUS_CHANGED: u8 = 0x08;
     /// **Draft.** `A=targetId, B=editing (0/1)` — an editing session began/ended.
     pub const EDITING_CHANGED: u8 = 0x09;
     /// **Draft.** `A=targetId, B=0` — the user committed a field (onSubmit).
     pub const SUBMIT: u8 = 0x0A;
     /// **Draft.** `A=targetId, B=offsetX (f32), C=offsetY (f32)` — scroll offset.
     pub const SCROLL: u8 = 0x0B;
     /// **Draft.** `A=targetId, B=deltaX (f32), C=deltaY (f32)` — wheel/trackpad.
     pub const WHEEL: u8 = 0x0C;
     /// **Draft.** `A=targetId, B=days since epoch (I32), C=millis of day (U32)`
     /// — a `DATE_PICKER`'s value changed (matches `PARAMETER::SET_DATE`).
     pub const DATE_CHANGED: u8 = 0x0D;
     /// **Draft.** Global navigation request (host → guest), never node-keyed.
     /// With the `NAVIGATE_URL` flag, `B` is a string offset (event arena /
     /// batch string section) to the destination URL; without it, the event means
     /// "back one step" (native back affordance) and `B`/`C` are ignored.
     pub const NAVIGATE: u8 = 0x0E;
     /// **Draft.** A bound `MEDIA_CONTROLLER`'s playback state changed
     /// (host → guest); `B` = 0/1. Reported only when `PLAYBACK_STATE` is bound.
     pub const MEDIA_PLAY_STATE_CHANGED: u8 = 0x0F;
     /// **Draft.** A bound controller's current position (host → guest); `B` =
     /// seconds (f32). Reported while playing; an app-initiated seek is not echoed.
     pub const MEDIA_TIME_UPDATED: u8 = 0x10;
     /// **Draft.** A bound controller reached the end of its media (host → guest).
     pub const MEDIA_ENDED: u8 = 0x11;
     /// **Draft.** A bound controller's volume changed (host → guest); `B` =
     /// volume (f32, 0..1).
     pub const MEDIA_VOLUME_CHANGED: u8 = 0x12;
     /// **Draft.** A `SIZE_THAT_FITS` slot's selected candidate index changed
     /// (host → guest); `B` = index (f32). Reported once after the first measure,
     /// then only when the derived fit index changes.
     pub const FIT_CHANGED: u8 = 0x13;
     /// **Draft.** A bound controller's media duration became known/changed
     /// (host → guest); `B` = seconds (f32). Reported when the resource loads and
     /// only when the value changes — never a stream.
     pub const MEDIA_DURATION_CHANGED: u8 = 0x14;
 }

 /// Commands within the `META` category.
 pub mod meta {
     /// Host must clear all rendered output.
     pub const RESET: u8 = 0x01;
     /// `A=fieldId (u16, low), B=field value` — a platform environment field
     /// (host → guest); see [`crate::environment`]. An extensible field family:
     /// each opcode sets one field (viewport, initial route, …).
     pub const ENVIRONMENT: u8 = 0x02;
     /// The host (renderer) requests a full snapshot of the current tree
     /// (host → guest). `A/B/C = 0`. Used for reconnect/gap recovery.
     pub const RESYNC: u8 = 0x03;
     /// A transport-liveness heartbeat probe (guest → host). `A/B/C = 0`, no
     /// payload. **Network batch transport only** (spec/OPCODE.md §Transport —
     /// heartbeat): the shared-memory ring MUST NOT emit, expect, or relay it.
     pub const PING: u8 = 0x04;
     /// The reply to `META::PING` (host → guest). `A/B/C = 0`, no payload.
     /// Network batch transport only (see [`PING`]).
     pub const PONG: u8 = 0x05;
     /// **Draft.** `A = mode` — renderer-wide color-scheme override
     /// (guest → host): `0` = platform-derived (default), `1` = light,
     /// `2` = dark. The renderer re-resolves every token-referencing property;
     /// while forced, platform scheme changes are ignored. See
     /// `spec/TOKENS.md` §Color Schemes.
     pub const SET_COLOR_SCHEME: u8 = 0x06;
     /// **Draft.** `A/B/C = 0` — clear every application design-token override
     /// (base + `dark.*`) and re-resolve against the renderer defaults
     /// (guest → host). Emit before a replacement theme's `SET_DESIGN_TOKEN`
     /// opcodes in the same frame.
     pub const RESET_THEME: u8 = 0x07;
     /// **Draft.** `A = fieldId (u16, low), B = value` — presentation metadata
     /// for the host window/surface that owns this stream (guest → host):
     /// title, description, locale (and future fields — an extensible family
     /// like [`ENVIRONMENT`]). Each field defines its own `B` encoding; today
     /// every field is a `STRING` offset (the arena / batch string-section
     /// convention). Renderer-global: survives `META::RESET`, and a full
     /// snapshot re-emits it. Each renderer maps the fields onto its own chrome;
     /// the browser mapping is `<title>` / `<meta name="description">` /
     /// `<html lang>`, not the protocol definition.
     pub const SET_WINDOW_METADATA: u8 = 0x08;
 }

 /// Window/surface metadata field ids for `META::SET_WINDOW_METADATA`
 /// (guest → host).
 ///
 /// Each opcode sets one field; new fields are new ids, never new commands
 /// (spec/OPCODE.md §Window metadata). An empty string clears the field and the
 /// renderer falls back to its default.
 pub mod window_field {
     /// The window/surface title (STRING in `B`).
     pub const TITLE: u16 = 0x0001;
     /// A human-readable description of the current content (STRING in `B`).
     /// Renderers map it to their own affordance (browser meta description,
     /// native accessible description, …).
     pub const DESCRIPTION: u16 = 0x0002;
     /// The content locale as a BCP 47 tag (STRING in `B`). The browser maps it
     /// to `<html lang>`; native renderers may use it for accessibility/formatting.
     pub const LOCALE: u16 = 0x0003;

     /// Every field this protocol version defines.
     pub const ALL: [u16; 3] = [TITLE, DESCRIPTION, LOCALE];
 }

 /// Values for `META::SET_COLOR_SCHEME`'s `A` field.
 pub mod color_scheme_mode {
     /// Follow the platform's native light/dark signal (default).
     pub const PLATFORM: u32 = 0;
     /// Force the light scheme.
     pub const LIGHT: u32 = 1;
     /// Force the dark scheme.
     pub const DARK: u32 = 2;
