     /// Every canonical name, in deterministic (spec, spec/ICONS.md) order.
     pub const NAMES: &[&str] = &[
         HOME, SETTINGS, SEARCH, MENU, CLOSE, CLOUD, CHEVRON_LEFT, CHEVRON_RIGHT,
         CHEVRON_UP, CHEVRON_DOWN, ARROW_LEFT, ARROW_RIGHT, ADD, REMOVE, CHECK,
