             int newId = fresh.id;
             int component = fresh.component;
             ops.add(() -> sink.createNode(newId, component));
             emitSubtreeInto(ops, fresh);
             int index = slot.nodeIndex;
             ops.add(() -> sink.insertChild(parentId, newId, index));
