/// The node evaluating on the computation stack — a computed signal or an effect.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Computation {
    Signal(usize),
    Effect(usize),
}

/// A reader of a signal (a computed or an effect).
#[derive(Clone, Copy, PartialEq, Eq)]
enum Subscriber {
    Signal(usize),
    Effect(usize),
}

