    pub fn create(&self, value: SignalValue) -> SignalId {
        let mut store = self.store.borrow_mut();
        let id = SignalId(store.cells.len() as u32);
        store.cells.push(Cell {
            value,
            compute: None,
            sources: Vec::new(),
            subscribers: Vec::new(),
            node_deps: Vec::new(),
            dirty: false,
            initialized: true,
